[metadata] {"type": "create", "filePath": "/workspace/repo/warehouse/utils/scanner_rules/pyarmor.yar", "content": "// SPDX-License-Identifier: Apache-2.0
//
// YARA-X rules for detecting PyArmor-encrypted content in uploaded
// distribution files. PyArmor obfuscates Python source by replacing it
// with an encrypted blob that is decrypted and executed at runtime by the
// PyArmor runtime. We do not allow such content on the index because it
// cannot be inspected.

rule pyarmor_encrypted_executor {
    meta:
        message = "PyArmor-encrypted content is not allowed"
    strings:
        // The bootstrap that hands the encrypted payload off to the PyArmor
        // runtime executor, e.g. `__pyarmor__(__name__, __file__, b'...')`
        // or `pyarmor(__name__, __file__, ...)`.
        $executor = "__pyarmor__("
        $pyarmor_call = "pyarmor(__name__"
    condition:
        any of them
}

rule pyarmor_encrypted_runtime {
    meta:
        message = "PyArmor-encrypted content is not allowed"
    strings:
        // Runtime hooks injected by PyArmor to protect obfuscated functions.
        $enter = "__pyarmor_enter__"
        $exit = "__pyarmor_exit__"
    condition:
        any of them
}
